public record Snapshot(
    string StreamId,
    long GlobalPosition,
    string StateJson,
    DateTime CreatedAt
);

public record OrderSnapshot(
    Guid OrderId,
    OrderStatus Status,
    decimal Total,
    List<OrderItem> Items,
    long Version
);

public async Task<Order> LoadAsync(Guid orderId, CancellationToken ct)
{
    var snapshot = await _repo.GetLatestSnapshotAsync(orderId, ct);
    var fromVersion = snapshot?.Version ?? -1;
    var state = snapshot != null 
        ? JsonSerializer.Deserialize<OrderState>(snapshot.StateJson)! 
        : new OrderState(orderId);
    var events = await _eventStore.ReadStreamAsync(
        orderId.ToString(), fromVersion + 1, ct);
    foreach (var e in events) state.Apply(e);
    return new Order(state);
}
